function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener('change', update);
    return () => mq.removeEventListener('change', update);
  }, []);
  return reduced;
}

const cx = (...c: (string | false | undefined)[]) => c.filter(Boolean).join(' ');

function Icon({ name, size, weight = 0 }: { name: string; size: number; weight?: number }) {
  return (
    <svg viewBox="0 0 1024 1024" width={size} height={size} fill="currentColor" stroke="currentColor"
      strokeWidth={weight} strokeLinejoin="round" aria-hidden="true" className={styles.icon}>
      {ICONS[name].map((d) => <path key={d} d={d} />)}
    </svg>
  );
}

function Mark({ muted, pop }: { muted?: boolean; pop?: boolean }) {
  return (
    <span className={cx(styles.mark, muted && styles.markMuted, pop && styles.pop)} aria-hidden="true">
      <Icon name="check" size={9} weight={80} />
    </span>
  );
}

function Button({ children, icon, tone = 'primary', className }: {
  children: ReactNode; icon?: string; tone?: 'primary' | 'success' | 'secondary'; className?: string | false;
}) {
  return (
    <span className={cx(styles.btn, tone === 'success' && styles.btnSuccess, tone === 'secondary' && styles.btnSecondary, className)}>
      <span className={styles.btnLabel}>{children}</span>
      {icon ? <span className={styles.btnTrail}><Icon name={icon} size={14} weight={48} /></span> : null}
    </span>
  );
}

interface CardProps {
  left: number;
  logo?: string;
  logoWidth: number;
  logoHeight: number;
  name: string;
  stage?: Stage;
  checks?: number;
  presses?: number;
  live?: boolean; // the card that animates
}

function IntegrationCard({ left, logo, logoWidth, logoHeight, name, stage = 'active', checks = 4, presses = 0, live }: CardProps) {
  const active = stage === 'active';
  return (
    <div className={styles.card} style={{ left, top: 54.5 }}>
      <div className={styles.cardHead}>
        <div className={styles.logo}>
          {logo
            // eslint-disable-next-line @next/next/no-img-element -- inline data-URI partner mark inside a self-contained animation, not a page image
            ? <img src={logo} alt={name} width={logoWidth} height={logoHeight} className={styles.logoImg} />
            : <span className={styles.logoName}>{name}</span>}
        </div>
        <span className={styles.sync}><Icon name="reload" size={12} weight={40} /></span>
      </div>
      <div className={styles.cardBody}>
        {active
          ? <span key="badge" className={cx(styles.badge, live && styles.pop)}>Synkar automatiskt</span>
          : (
            <div key="note" className={cx(styles.note, stage === 'available' && styles.notePlain)}>
              {stage === 'pending' ? <Icon name="loading" size={14} weight={40} /> : null}
              <span>{stage === 'pending' ? 'Väntar på godkännande' : 'Tillgänglig för integration'}</span>
            </div>
          )}
        <div className={styles.types}>
          {TAX_TYPES.map((label, k) => {
            const done = k < checks;
            return (
              <div key={label} className={styles.type}>
                <Mark key={done ? 'done' : 'open'} muted={!done} pop={live && done} />
                <span className={styles.typeLabel}>{label}</span>
              </div>
            );
          })}
        </div>
      </div>
      <div className={styles.cardFoot}>
        {active
          ? <Button key="hantera" tone="success" icon="setting" className={live && styles.pop}>Hantera</Button>
          : <Button key={'aktivera-' + presses} tone="secondary" icon="link" className={presses > 0 && styles.press}>Aktivera</Button>}
      </div>
    </div>
  );
}

export interface IntegrationsScreenAnimationProps {
  /** Replay from the start after the 5.4 s timeline. Default true. */
  loop?: boolean;
  className?: string;
  /** Media freezes it (not unmounts) once its frame scrolls out of view. */
  paused?: boolean;
}

export function IntegrationsScreenAnimation({ loop = true, className, paused = false }: IntegrationsScreenAnimationProps) {
  const reduced = usePrefersReducedMotion();
  const [s, setS] = useState<AnimState>(INITIAL);

  // A ref, not a dependency of the timeline effect below — toggling it
  // shouldn't tear down and reset the whole state machine, just stop the
  // timeline advancing to its next step until it's false again.
  const pausedRef = useRef(paused);
  useEffect(() => {
    pausedRef.current = paused;
  }, [paused]);
  const pumpRef = useRef<() => void>(() => {});

  useEffect(() => {
    let alive = true;
    let i = 0;
    let timer: ReturnType<typeof setTimeout> | undefined;
    // Guarded so it's safe to call redundantly: does nothing if a step is
    // already pending or the timeline is paused, so the separate "resume"
    // effect below can just call it again once unpaused without risking
    // two steps firing in parallel.
    const pump = () => {
      if (!alive || timer !== undefined || pausedRef.current) return;
      timer = setTimeout(() => {
        timer = undefined;
        if (!alive) return;
        setS(STEPS[i][1]);
        i += 1;
        if (i >= STEPS.length) {
          if (!loop) return;
          i = 0;
        }
        pump();
      }, STEPS[i][0]);
    };
    pumpRef.current = pump;
    pump();
    return () => {
      alive = false;
      if (timer !== undefined) clearTimeout(timer);
    };
  }, [loop]);

  // Resumes the timeline right where it stopped once unpaused.
  useEffect(() => {
    if (!paused) pumpRef.current();
  }, [paused]);

  const cameraStyle: CSSProperties = {
    transform: CAMERA[s.shot],
    transition: reduced ? 'none' : s.shotTransition,
  };
  const pointerIn = s.pointer === 'in';
  const pointerStyle: CSSProperties = {
    opacity: pointerIn ? 1 : 0,
    transform: pointerIn ? 'translate(0px, 0px)' : 'translate(9.6px, 16px)',
    transition: reduced || s.pointer === 'hidden'
      ? 'none'
      : pointerIn
        ? 'opacity 220ms ' + EASE.snap + ', transform 220ms ' + EASE.snap
        : 'opacity 180ms ' + EASE.exit + ', transform 180ms ' + EASE.exit,
  };

  return (
    <div className={cx(styles.canvas, className)} aria-hidden="true">
      <div className={styles.camera} style={cameraStyle}>
        <div className={styles.page}>
          <section className={styles.hero}>
            <div className={styles.heroTitle}>Data</div>
            <div className={styles.drop}>
              <Icon name="cloud-upload" size={24} />
              <span className={styles.dropText}>Ladda upp filer för att komma igång</span>
            </div>
            <div className={styles.sources}>
              <span className={styles.source}><Mark /><span>SIE</span></span>
              <span className={styles.source}><Mark /><span>Huvudbok i Excel</span><span className={styles.link}>Ladda ned mall</span></span>
              <span className={styles.source}>
                <Mark /><span>Periodsammanställning</span><span className={styles.link}>Moms</span><span>och</span><span className={styles.link}>AGA</span>
              </span>
            </div>
          </section>

          <nav className={styles.viewSwitch}>
            <div className={styles.segmented}>
              {VIEWS.map(([label, width], k) => (
                <span key={label} className={cx(styles.segItem, k === 0 && styles.segItemOn)} style={{ width }}>{label}</span>
              ))}
            </div>
            <span className={styles.viewAction}><Button>Hantera räkenskapsår</Button></span>
          </nav>

          <section className={styles.integrations}>
            <div className={styles.panelTitle}>Läs in data via integration</div>
            <IntegrationCard left={16} name="Handelsbanken" logoWidth={150} logoHeight={21} />
            <IntegrationCard left={326} name="Spiris" logo={LOGO_SPIRIS} logoWidth={80} logoHeight={25} />
            <IntegrationCard left={636} name="Skatteverket" logo={LOGO_SKATTEVERKET} logoWidth={128.5} logoHeight={24}
              stage={s.stage} checks={s.checks} presses={s.presses} live />
            <IntegrationCard left={946} name="Fortnox" logo={LOGO_FORTNOX} logoWidth={97.4} logoHeight={21} />
            <IntegrationCard left={1256} name="Björn Lundén" logo={LOGO_BJORN_LUNDEN} logoWidth={75.5} logoHeight={25} />
          </section>

          <section className={styles.types2}>
            <div className={styles.panelTitle}>Datatyper</div>
          </section>
        </div>

        <div className={styles.pointer} style={pointerStyle}>
          <svg viewBox="0 0 24 24" width="24" height="24" className={styles.pointerSvg}>
            <path d="M5 2 L5 19 L9.6 14.6 L12.4 21.4 L15.6 20 L12.8 13.4 L19 13.4 Z"
              fill="var(--isc-ink)" stroke="var(--isc-white)" strokeWidth="1.4" strokeLinejoin="round" />
          </svg>
        </div>
      </div>
    </div>
  );
}


